package com.d104.pnt.ui.game.playimport androidx.lifecycle.SavedStateHandleimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewModelScopeimport com.d104.pnt.data.repository.AuthRepositoryimport com.d104.pnt.data.repository.GameSessionEventimport com.d104.pnt.data.repository.GameSessionRepositoryimport com.d104.pnt.domain.model.GameRoleimport com.d104.pnt.navigation.NavArgsimport com.d104.pnt.util.socket.GameSocketManagerimport dagger.hilt.android.lifecycle.HiltViewModelimport kotlinx.coroutines.delayimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.flow.firstimport kotlinx.coroutines.launchimport timber.log.Timberimport javax.inject.Inject@HiltViewModelclass GameRoleViewModel @Inject constructor(    private val authRepository: AuthRepository,    private val gameSocketManager: GameSocketManager,    private val savedStateHandle: SavedStateHandle,    private val gameSessionRepository: GameSessionRepository) : ViewModel() {    private val roomId: Long = savedStateHandle.get<Long>(NavArgs.ROOM_ID) ?: 0L    private val roleName: String = savedStateHandle.get<String>(NavArgs.ROLE) ?: "THIEF"    val role: GameRole = GameRole.fromName(roleName)    private val _flowStatus = MutableStateFlow<GameFlowStatus>(GameFlowStatus.RoleReveal(role))    val flowStatus = _flowStatus.asStateFlow()    private val _connectionStatus = MutableStateFlow<ConnectionStatus>(ConnectionStatus.Connecting)    val connectionStatus = _connectionStatus.asStateFlow()//    init {//        // 바로 역할 보여주면서 백그라운드로 소켓 연결//        setupListeners()//        connectAndJoin()//    }    init {        gameSessionRepository.connectAndJoin(roomId)        Timber.d("RoomId: $roomId")        observeRepositoryEvents()    }    private fun observeRepositoryEvents() {        viewModelScope.launch {            gameSessionRepository.eventFlow.collect { event ->                when (event) {                    is GameSessionEvent.GameStarted -> {                        Timber.d("🚀 레포지토리에서 게임 시작 신호 수신!")                        _flowStatus.value = GameFlowStatus.CountDown(event.gameId)                    }                    is GameSessionEvent.GameEnded -> {                        Timber.d("레포지토리에서 게임 종료 신호 수신!")                    }                    is GameSessionEvent.ErrorOccurred -> {                        Timber.e("레포지토리에서 에러 발생: ${event.message}")                    }                    is GameSessionEvent.NavigateToNews -> {}                }            }        }    }    private fun setupListeners() {        // Join 성공 확인 (로그용)        gameSocketManager.setOnJoinedRoom { gameId, memberId, message ->        }        // get will start game        gameSocketManager.setOnWillStartGame { gameId, willStartAt ->            Timber.d("⏰ 5초 후 게임 시작 - gameId: $gameId, willStartAt: $willStartAt")            _connectionStatus.value = ConnectionStatus.WillStart(willStartAt)        }        // get start game - 도둑 도망 화면으로 이동        gameSocketManager.setOnGameStarted { gameId, startTime ->            Timber.d("🏁 게임 시작! - gameId: $gameId, startTime: $startTime")            _flowStatus.value = GameFlowStatus.CountDown(gameId)        }        gameSocketManager.setOnJoinedRoom { gameId, memberId, message ->            Timber.d("✅ 게임 입장 성공: gameId=$gameId, memberId=$memberId")            _connectionStatus.value = ConnectionStatus.Joined        }    }    private fun connectAndJoin() {        viewModelScope.launch {            try {                val token = authRepository.getAccessToken().first()                if (token.isEmpty()) {                    Timber.e("❌ 토큰이 비어있음")                    return@launch                }                // 게임 소켓 연결 (백그라운드)                Timber.d("🔌 게임 소켓 연결 시도...")                gameSocketManager.connect(token)                // 연결 대기                var retryCount = 0                while (!gameSocketManager.isConnected() && retryCount < 50) {                    delay(100)                    retryCount++                }                if (!gameSocketManager.isConnected()) {                    Timber.e("❌ 게임 소켓 연결 실패")                    _connectionStatus.value = ConnectionStatus.Error("서버 연결 실패")                    return@launch                }                Timber.d("✅ 게임 소켓 연결 성공")                _connectionStatus.value = ConnectionStatus.Connected                // 게임 입장                gameSocketManager.joinGame(roomId)                delay(1000)                if (_connectionStatus.value !is ConnectionStatus.Joined) {                    Timber.w("⚠️ Join 응답을 받지 못했지만 계속 진행")                }            } catch (e: Exception) {                Timber.e(e, "❌ 게임 연결 중 오류 발생")            }        }    }}sealed class GameFlowStatus {    data class RoleReveal(val role: GameRole) : GameFlowStatus()    data class CountDown(val gameId: Long) : GameFlowStatus()}// ⭐ 연결 상태 추가sealed class ConnectionStatus {    object Connecting : ConnectionStatus()    object Connected : ConnectionStatus()    object Joined : ConnectionStatus()    data class WillStart(val willStartAt: String) : ConnectionStatus()    data class Error(val message: String) : ConnectionStatus()}